package com.chatgptcourses.support.service;

import static com.chatgptcourses.account.service.AccountOperations.*;
import static com.chatgptcourses.support.service.SupportTypes.*;
import com.chatgptcourses.account.service.AccountOperations;
import com.chatgptcourses.notifications.TransactionalNotifications;
import com.chatgptcourses.shared.http.ApiError;
import com.chatgptcourses.shared.http.EntityTags;
import com.chatgptcourses.shared.http.RevisionPreconditions;
import java.util.*;
import java.sql.Timestamp;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Isolation;
import org.springframework.transaction.annotation.Transactional;

@Service
public class SupportService {
    private static final Set<String> STATES=Set.of("OPEN","IN_PROGRESS","WAITING_FOR_USER","RESOLVED","CLOSED");
    private final AccountOperations db;private final TransactionalNotifications notifications;private final com.chatgptcourses.operations.service.ContentCaseService cases;
    public SupportService(AccountOperations db,TransactionalNotifications notifications,com.chatgptcourses.operations.service.ContentCaseService cases){this.db=db;this.notifications=notifications;this.cases=cases;}
    @Transactional(readOnly=true,isolation=Isolation.REPEATABLE_READ)
    public SupportTicketPage list(UUID actor,boolean admin,String state,int page,int size){db.authorization.require(actor,admin?"support.admin.read":"support.read");page(page,size);if(state!=null)check(STATES.contains(state));String where=" WHERE 1=1";List<Object> args=new ArrayList<>();if(!admin){where+=" AND owner_id=?";args.add(actor);}if(state!=null){where+=" AND state=?";args.add(state);}long total=db.jdbc.queryForObject("SELECT count(*) FROM support_tickets"+where,Long.class,args.toArray());args.add(size);args.add((long)page*size);var items=db.jdbc.query("SELECT id FROM support_tickets"+where+" ORDER BY created_at DESC,id LIMIT ? OFFSET ?",(r,n)->r.getObject(1,UUID.class),args.toArray()).stream().map(id->ticket(actor,id,admin,false).value()).toList();return new SupportTicketPage(items,page,size,total);}
    @Transactional
    public SupportTicketCreation create(UUID actor,UUID accountContext,String idempotencyKey,CreateSupportTicket command){db.authorization.mutation(actor,accountContext,"support.write");check(command!=null&&command.category()!=null&&Set.of("TECHNICAL","CONTENT","ACCESS","ORDER","ACCOUNT","OTHER").contains(command.category()));text(command.subject(),160);text(command.message(),8000);locale(command.locale());attachments(command.attachmentIds());db.bound(command,48*1024);UUID key=key(idempotencyKey);byte[] hash=db.hash(command);db.lock(actor);db.authorization.mutation(actor,accountContext,"support.write");UUID old=db.replay(actor,"TICKET_CREATE",key,hash);if(old!=null)return new SupportTicketCreation(ticket(actor,old,false,false).value(),false);validateContext(actor,command.context());validateSelections(actor,command.attachmentIds());UUID id=UUID.randomUUID();var stamp=clock();db.jdbc.update("INSERT INTO support_tickets(id,owner_id,category,subject,locale,context_json,state,created_at,updated_at) VALUES(?,?,?,?,?,?::jsonb,'OPEN',?,?)",id,actor,command.category(),command.subject(),command.locale(),command.context()==null?null:db.json(command.context()),stamp,stamp);add(actor,actor,id,"USER",command.message(),command.attachmentIds(),stamp);event(actor,id,"USER","CREATED",null,"OPEN",null,stamp);if("CONTENT".equals(command.category()))cases.reportFromSupport(actor,id,command.context());db.remember(actor,"TICKET_CREATE",key,hash,"ticket_id",id);return new SupportTicketCreation(ticket(actor,id,false,false).value(),true);}
    @Transactional(readOnly=true)
    public SupportTicketView get(UUID actor,UUID id,boolean admin){db.authorization.require(actor,admin?"support.admin.read":"support.read");return ticket(actor,id,admin,false).value();}
    @Transactional(readOnly=true,isolation=Isolation.REPEATABLE_READ)
    public SupportMessagePage messages(UUID actor,UUID id,boolean admin,int page,int size){db.authorization.require(actor,admin?"support.admin.read":"support.read");ticket(actor,id,admin,false);page(page,size);long total=db.jdbc.queryForObject("SELECT count(*) FROM support_messages WHERE ticket_id=?",Long.class,id);var items=db.jdbc.query("SELECT id FROM support_messages WHERE ticket_id=? ORDER BY created_at,id LIMIT ? OFFSET ?",(r,n)->r.getObject(1,UUID.class),id,size,(long)page*size).stream().map(this::message).toList();return new SupportMessagePage(items,page,size,total);}
    @Transactional(readOnly=true,isolation=Isolation.REPEATABLE_READ)
    public SupportEventPage events(UUID actor,UUID id,boolean admin,int page,int size){db.authorization.require(actor,admin?"support.admin.read":"support.read");ticket(actor,id,admin,false);page(page,size);long total=db.jdbc.queryForObject("SELECT count(*) FROM support_ticket_events WHERE ticket_id=?",Long.class,id);var items=db.jdbc.query("SELECT * FROM support_ticket_events WHERE ticket_id=? ORDER BY created_at,id LIMIT ? OFFSET ?",(r,n)->new SupportTicketEvent(r.getObject("id",UUID.class),id,r.getString("event_type"),r.getString("from_state"),r.getString("to_state"),r.getString("author_kind"),r.getString("reason"),instant(r,"created_at")),id,size,(long)page*size);return new SupportEventPage(items,page,size,total);}
    @Transactional
    public SupportMessageCreation addMessage(UUID actor,UUID context,UUID id,boolean admin,String ifMatch,String idempotencyKey,AddSupportMessage command){String permission=admin?"support.reply":"support.write";db.authorization.mutation(actor,context,permission);check(command!=null);text(command.message(),8000);attachments(command.attachmentIds());if(admin)check(command.attachmentIds().isEmpty());db.bound(command,48*1024);UUID key=key(idempotencyKey);byte[] hash=db.hash(Arrays.asList(id,admin,command));var initial=ticket(actor,id,admin,false);lockActors(actor,initial.owner());var t=ticket(actor,id,admin,true);db.authorization.mutation(actor,context,permission);UUID old=db.replay(actor,"TICKET_MESSAGE",key,hash);if(old!=null)return new SupportMessageCreation(new SupportConversationUpdate(t.value(),message(old)),false);RevisionPreconditions.requireMatch(ifMatch,tag(t.value()));if("CLOSED".equals(t.value().state()))throw error(ApiError.SUPPORT_TICKET_CLOSED);validateSelections(t.owner(),command.attachmentIds());var stamp=ticketStamp(id);UUID msg=add(actor,t.owner(),id,admin?"SUPPORT":"USER",command.message(),command.attachmentIds(),stamp);String next=admin?"WAITING_FOR_USER":"OPEN";update(id,next,stamp);event(actor,id,admin?"SUPPORT":"USER",admin?"SUPPORT_REPLY":"USER_MESSAGE",t.value().state(),next,null,stamp);if(admin){String email=db.jdbc.queryForObject("SELECT normalized_email FROM user_accounts WHERE id=?",String.class,t.owner());notifications.supportReply(msg,t.owner(),email,t.value().locale(),id);}db.remember(actor,"TICKET_MESSAGE",key,hash,"message_id",msg);return new SupportMessageCreation(new SupportConversationUpdate(ticket(actor,id,admin,false).value(),message(msg)),true);}
    @Transactional
    public SupportTicketView changeState(UUID actor,UUID context,UUID id,String ifMatch,String idempotencyKey,ChangeSupportState command){db.authorization.mutation(actor,context,"support.manage");check(command!=null&&command.state()!=null&&STATES.contains(command.state()));text(command.reason(),2000);UUID key=key(idempotencyKey);byte[] hash=db.hash(Arrays.asList(id,command));var initial=ticket(actor,id,true,false);lockActors(actor,initial.owner());var t=ticket(actor,id,true,true);db.authorization.mutation(actor,context,"support.manage");if(db.replay(actor,"TICKET_STATE",key,hash)!=null)return t.value();RevisionPreconditions.requireMatch(ifMatch,tag(t.value()));if(!t.value().state().equals(command.state())){var stamp=ticketStamp(id);update(id,command.state(),stamp);event(actor,id,"SUPPORT","STATE_CHANGED",t.value().state(),command.state(),command.reason(),stamp);}db.remember(actor,"TICKET_STATE",key,hash,"ticket_id",id);return ticket(actor,id,true,false).value();}
    private void lockActors(UUID actor,UUID owner){java.util.stream.Stream.of(actor,owner).distinct().sorted().forEach(db::lock);}
    private UUID add(UUID actor,UUID owner,UUID ticket,String kind,String body,List<UUID> attachments,Timestamp stamp){UUID id=UUID.randomUUID();db.jdbc.update("INSERT INTO support_messages(id,ticket_id,owner_id,actor_id,author_kind,body,created_at) VALUES(?,?,?,?,?,?,?)",id,ticket,owner,actor,kind,body,stamp);for(var asset:attachments)db.jdbc.update("INSERT INTO support_message_attachments(message_id,ticket_id,owner_id,asset_id) VALUES(?,?,?,?)",id,ticket,owner,asset);return id;}
    private void update(UUID id,String state,Timestamp stamp){db.jdbc.update("UPDATE support_tickets SET state=?,revision=revision+1,updated_at=? WHERE id=?",state,stamp,id);}
    private void event(UUID actor,UUID id,String kind,String type,String from,String to,String reason,Timestamp stamp){db.jdbc.update("INSERT INTO support_ticket_events(id,ticket_id,actor_id,author_kind,event_type,from_state,to_state,reason,created_at) VALUES(?,?,?,?,?,?,?,?,?)",UUID.randomUUID(),id,actor,kind,type,from,to,reason,stamp);}
    private Timestamp clock(){return db.jdbc.queryForObject("SELECT clock_timestamp()",Timestamp.class);}
    // Under the ticket lock, strictly follow every persisted child and reuse this instant for the whole action.
    private Timestamp ticketStamp(UUID id){return db.jdbc.queryForObject("SELECT greatest(clock_timestamp(),t.created_at,t.updated_at+interval '1 microsecond',coalesce((SELECT max(m.created_at)+interval '1 microsecond' FROM support_messages m WHERE m.ticket_id=t.id),t.created_at),coalesce((SELECT max(e.created_at)+interval '1 microsecond' FROM support_ticket_events e WHERE e.ticket_id=t.id),t.created_at)) FROM support_tickets t WHERE t.id=?",Timestamp.class,id);}
    private Ticket ticket(UUID actor,UUID id,boolean admin,boolean lock){var rows=db.jdbc.query("SELECT * FROM support_tickets WHERE id=?"+(admin?"":" AND owner_id=?")+(lock?" FOR UPDATE":""),(r,n)->new Ticket(r.getObject("owner_id",UUID.class),new SupportTicketView(id,r.getLong("revision"),r.getString("category"),r.getString("subject"),r.getString("locale"),r.getString("state"),r.getString("context_json")==null?null:db.mapper.readValue(r.getString("context_json"),SupportContext.class),instant(r,"created_at"),instant(r,"updated_at"))),admin?new Object[]{id}:new Object[]{id,actor});if(rows.isEmpty())throw error(ApiError.RESOURCE_NOT_FOUND);return rows.getFirst();}
    private SupportMessageView message(UUID id){return db.jdbc.queryForObject("SELECT * FROM support_messages WHERE id=?",(r,n)->new SupportMessageView(id,r.getObject("ticket_id",UUID.class),r.getString("author_kind"),r.getString("body"),db.jdbc.query("SELECT a.* FROM support_message_attachments s JOIN assets a ON a.id=s.asset_id WHERE s.message_id=? ORDER BY a.id",(a,k)->new SupportAttachment(a.getObject("id",UUID.class),a.getString("filename"),a.getString("verified_content_type"),a.getLong("verified_size"),hex(a.getBytes("content_sha256"))),id),instant(r,"created_at"),"USER".equals(r.getString("author_kind"))?"NOT_REQUIRED":notification(id)),id);}
    private String notification(UUID message){var rows=db.jdbc.query("SELECT status FROM notification_outbox WHERE business_key=?",(r,n)->r.getString(1),"support:reply:"+message);if(rows.isEmpty())return "PENDING";return switch(rows.getFirst()){case "SENT"->"SENT";case "DEAD","RETRY","INDETERMINATE"->"ISSUE";default->"PENDING";};}
    private static void attachments(List<UUID> ids){check(ids!=null&&ids.size()<=5&&ids.stream().allMatch(Objects::nonNull)&&new HashSet<>(ids).size()==ids.size());}
    private void validateSelections(UUID owner,List<UUID> ids){for(var id:ids)if(!Boolean.TRUE.equals(db.jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM assets WHERE id=? AND owner_id=? AND scope='PROJECT_FILE' AND state='READY' AND content_sha256 IS NOT NULL)",Boolean.class,id,owner)))throw error(ApiError.SUPPORT_ATTACHMENT_INVALID);}
    private void validateContext(UUID owner,SupportContext c){if(c==null)return;check(c.resourceId()!=null||c.orderId()!=null||c.projectId()!=null||c.enrollmentId()!=null);locale(c.locale());check((c.resourceId()==null)==(c.versionId()==null));if(c.resourceId()!=null){locale(c.locale());if(!Boolean.TRUE.equals(db.jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM pedagogical_versions WHERE id=? AND resource_id=?)",Boolean.class,c.versionId(),c.resourceId())))throw error(ApiError.RESOURCE_NOT_FOUND);}else check(c.revisionId()==null);if(c.revisionId()!=null&&!Boolean.TRUE.equals(db.jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM editorial_revisions e JOIN content_translations t ON t.id=e.translation_id WHERE e.id=? AND t.pedagogical_version_id=? AND t.locale=?)",Boolean.class,c.revisionId(),c.versionId(),c.locale())))throw error(ApiError.RESOURCE_NOT_FOUND);if(c.orderId()!=null)ownTarget("orders",owner,c.orderId());if(c.projectId()!=null)ownTarget("projects",owner,c.projectId());if(c.enrollmentId()!=null)ownTarget("learning_enrollments",owner,c.enrollmentId());if(c.projectId()!=null&&c.versionId()!=null&&!Boolean.TRUE.equals(db.jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM projects WHERE id=? AND source_activity_id=? AND source_version_id=?)",Boolean.class,c.projectId(),c.resourceId(),c.versionId())))throw error(ApiError.VALIDATION_FAILED);}
    private void ownTarget(String table,UUID actor,UUID id){if(!Boolean.TRUE.equals(db.jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM "+table+" WHERE id=? AND owner_id=?)",Boolean.class,id,actor)))throw error(ApiError.RESOURCE_NOT_FOUND);}
    public static String tag(SupportTicketView value){return EntityTags.forRevision("support-ticket",value.id(),value.revision());}
    @Transactional(readOnly=true)
    public SupportMessageView messageForOperator(UUID actor,UUID ticketId,UUID messageId){db.authorization.require(actor,"support.admin.read");ticket(actor,ticketId,true,false);if(!Boolean.TRUE.equals(db.jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM support_messages WHERE id=? AND ticket_id=?)",Boolean.class,messageId,ticketId)))throw error(ApiError.RESOURCE_NOT_FOUND);return message(messageId);}
    private record Ticket(UUID owner,SupportTicketView value) { }
}
